def F(expr,variables,units=None,assumptions=None):
 return {'expression':expr,'variables':variables,'units':units or {},'assumptions':assumptions or []}
mdh=F('T_(i−1,i)=Rx(α_(i−1)) Dx(a_(i−1)) Rz(θ_i) Dz(d_i)',{'T_(i−1,i)':'homogeneous transform mapping coordinates from frame i into frame i−1','Rx,Rz':'homogeneous rotations about the named coordinate axis','Dx,Dz':'homogeneous translations along the named coordinate axis','α_(i−1)':'preceding link twist','a_(i−1)':'preceding link length','θ_i':'current joint angle','d_i':'current link offset'},{'a,d':'length units','α,θ':'radians unless explicitly marked degrees'},['Use the displayed factor order and column vectors.'])
add(256,'modified-dh-product','Ordered homogeneous transformation','Which ordered product is printed for the transform from frame i into frame i−1?', ['Rx(α_(i−1)) Dx(a_(i−1)) Rz(θ_i) Dz(d_i)','Rz(θ_i) Dz(d_i) Rx(α_(i−1)) Dx(a_(i−1))','Rx(θ_i) Dx(d_i) Rz(α_(i−1)) Dz(a_(i−1))','Dx(d_i) Rz(α_(i−1)) Rx(θ_i) Dz(a_(i−1))'],0,'The displayed product applies the preceding-link x rotation and translation before the current z rotation and translation in matrix-product order.', ['This reproduces the displayed factorization.','This exchanges the preceding-link and current-joint factor blocks; they do not generally commute.','This exchanges x/z parameter roles.','This also exchanges lengths and angular roles between the named axes.'],typ='sequence',formulas=[mdh])
add(256,'modified-dh-product','Translation in the modified DH product','In Rx(α) Dx(a) Rz(θ) Dz(d), what is the resulting translation column?', ['(a, −d sinα, d cosα)','(a cosθ, a sinθ, d)','(a, d sinα, d cosα)','(a cosα, a sinα, d)'],0,'The z translation is rotated by Rx(α), giving (0,−d sinα,d cosα), and the x translation adds (a,0,0).', ['This follows the displayed product.','This resembles a different factor order and is not this product.','The y component has the wrong sign for the displayed right-handed Rx matrix.','The x translation is along the x rotation axis and is not rotated into y.'],typ='derivation',steps=['Rx leaves the x-axis translation (a,0,0) unchanged.','Rz leaves its own z-axis translation (0,0,d) unchanged.','Rx maps (0,0,d) to (0,−d sinα,d cosα).','Add the two translations.'],formulas=[mdh],assumptions=['α=α_(i−1), a=a_(i−1), θ=θ_i and d=d_i are shortened notation.'])
add(256,'dh-source-error','Checking the displayed transform','The expanded matrix prints sinα_i in row3,column2; deriving that entry from Rx(α_(i−1))Rz(θ_i), which expression is required?', ['sinα_(i−1) cosθ_i','sinα_i','cosα_(i−1) sinθ_i','−sinα_(i−1)'],0,'Row3 of Rx is (0,sinα,cosα); column2 of Rz is (−sinθ,cosθ,0), so the dot product is sinα cosθ.', ['This is the dot product from the printed factors.','This reproduces the inconsistent expanded entry, not the product.','This swaps sine/cosine factors and corresponds to another entry.','This is the row2,column3 entry, not row3,column2.'],typ='derivation',steps=['Use α=α_(i−1) and θ=θ_i.','Dot (0,sinα,cosα) with (−sinθ,cosθ,0).','The result is sinα cosθ.','Treat the printed sinα_i entry as a source inconsistency.'],formulas=[mdh,F('R_32=sinα cosθ',{'R_32':'third-row, second-column rotation entry','α':'preceding-link twist α_(i−1)','θ':'joint angle θ_i'},{'angles':'radians unless marked degrees'})],assumptions=['Derive from the factorization instead of accepting the inconsistent expanded entry as a rule.'],evidence={256:'Displayed factorization: Rx(α_(i−1)) Dx(a_(i−1)) Rz(θ_i) Dz(d_i). Expanded third row prints sinθ_i sinα_(i−1), sinα_i, cosα_(i−1), d_i cosα_(i−1). The second entry is inconsistent with the product.'})
add(256,'modified-dh-product','Numerical modified-DH translation','Use α=90°, a=2 m, θ=0° and d=3 m in the printed factorization; what is the translation column?', ['(2,−3,0) m','(2,0,3) m','(0,2,3) m','(2,3,0) m'],0,'The translation is (a,−d sinα,d cosα)=(2,−3,0) m.', ['This uses sin90°=1 and cos90°=0.','This omits the x-axis rotation of the z offset.','This rotates the a translation incorrectly.','This reverses the sign of the y component.'],typ='numerical',steps=['sin90°=1 and cos90°=0.','Substitute into (a,−d sinα,d cosα).','Obtain (2,−3,0) m.'],formulas=[mdh],assumptions=['Use the displayed factorization, not the erroneous expanded row3,column2.'])
add(257,'dh-frame-assignment','Assigning the joint axis','According to the frame-assignment steps, which axis is placed along joint axis i?', ['z_i','x_i','y_i','The translation column of every preceding transform'],0,'The procedure places z_i along joint axis i.', ['This is the stated assignment.','x_i is chosen along the common normal or normal to the plane of intersecting axes.','y_i completes the right-handed frame.','A translation column is not a coordinate axis assignment.'],typ='definition',diff='easy')
add(257,'dh-frame-assignment','Common normal and frame origin','For two nonintersecting joint axes, which construction follows the stated procedure?', ['Choose their common perpendicular and place the origin where it meets axis i','Place the origin at the midpoint of the physical link regardless of its joint axes','Set x_i along axis i and choose the origin at the tool tip','Set every frame origin equal to the base origin regardless of geometry'],0,'The origin is placed where the common perpendicular meets axis i, with x_i along that perpendicular.', ['This is the stated common-normal construction.','A link-body midpoint need not satisfy the common-normal rule.','z_i, not x_i, follows axis i in this convention.','Link frames generally have distinct geometry-dependent origins.'],typ='scenario')
add(257,'dh-frame-assignment','Intersecting axes and frame completion','When adjacent axes intersect, which pair follows the slide’s remaining frame rules?', ['Choose x_i normal to their plane and y_i to complete a right-handed frame','Choose x_i along both distinct axes and y_i parallel to x_i','Choose y_i first and omit x_i because the common-normal distance is zero','Choose a left-handed frame to compensate for zero link length'],0,'At an intersection, x_i is normal to the axes’ plane; y_i then completes the right-handed system.', ['This preserves both stated rules.','Distinct intersecting axes cannot both be one x direction, and parallel x/y would not form a frame.','Zero common-normal distance does not remove an axis from the coordinate frame.','The stated convention remains right-handed.'],typ='scenario',assumptions=['The intersecting axes are not collinear, so their plane is defined.'])
