wheel=F('v=(v_r+v_l)/2=r(u_r+u_l)/2; ω=(v_r−v_l)/(2d)=r(u_r−u_l)/(2d)',{'v':'forward speed at axle midpoint','ω':'counterclockwise yaw rate','v_r,v_l':'right and left wheel linear speeds','u_r,u_l':'right and left wheel angular rates','r':'common wheel radius','d':'half the wheel-center separation'},{'v,v_r,v_l':'m/s','ω,u_r,u_l':'rad/s','r,d':'m'},['Equal wheel radii, pure rolling, no lateral slip, flat plane.'])
pose=F('x_dot=v cosφ; y_dot=v sinφ; φ_dot=ω',{'x_dot,y_dot':'base-frame velocity components of axle midpoint','v':'forward speed at axle midpoint','φ':'heading measured counterclockwise from the base-frame +x axis','φ_dot,ω':'counterclockwise heading rate'},{'x_dot,y_dot,v':'m/s','φ':'radians unless marked degrees','φ_dot,ω':'rad/s'},['Flat plane and no lateral slip.'])
add(262,'differential-drive-layout','Wheel geometry and controls','In the differential-drive figure, which interpretation of r and2d is correct?', ['r is each wheel radius;2d is the separation between wheel centers','r is wheel diameter;2d is distance from axle midpoint to one wheel','r is turn radius;2d is wheel circumference','r is axle length;2d is heading angle'],0,'The figure labels wheel radius r and two half-width segments d across the axle.', ['This matches the physical geometry.','This doubles the radius and halves the axle separation incorrectly.','Turning radius varies with speeds and is not the wheel radius.','The labels are lengths, not a heading angle.'],typ='diagram',diff='easy',evidence={262:'Differential-drive sketch: wheel radius r; axle center between left and right wheels; each center-to-wheel half-distance is d, giving total separation2d; headingφ is measured counterclockwise from+x.'})
add(262,'wheel-angular-linear','Angular versus linear wheel speed','Which relation converts the right wheel angular rate u_r into its linear rolling speed?', ['v_r=r u_r','v_r=u_r/r','v_r=2d u_r','v_r=r²u_r'],0,'Tangential speed is wheel radius times angular rate.', ['Length times radians per second gives rolling speed in m/s.','This has inverse-length dependence and incorrect units.','The axle separation is not the wheel rolling radius.','This introduces an extra length factor.'],typ='conceptual',formulas=[wheel])
add(263,'drive-motion-cases','Equal wheel speeds','Under pure rolling, what follows when v_r=v_l?', ['Zero yaw rate, with straight translation if the common speed is nonzero','Positive yaw rate for every common speed','Rotation in place for every common speed','A yaw rate determined only by wheel radius, regardless of the common speeds'],0,'The wheel-speed difference is zero; if both speeds are zero the robot is stationary rather than translating.', ['This distinguishes straight motion from the zero-speed special case.','A positive yaw rate requires a positive difference.','In-place rotation uses equal and opposite speeds, not equal same-sign speeds.','Yaw depends on the speed difference and wheel separation.'],typ='conceptual',formulas=[wheel])
add([263,265],'drive-motion-cases','Direction of yaw','With positive counterclockwise yaw and equal wheel radii, what does v_r>v_l imply?', ['Positive yaw rate','Negative yaw rate','Zero yaw rate','Zero forward speed necessarily'],0,'ω=(v_r−v_l)/(2d)>0 for d>0.', ['This follows the stated sign convention.','This reverses the right-minus-left sign.','The speeds are unequal, so the difference is nonzero.','The average is zero only for equal and opposite speeds.'],typ='conceptual',formulas=[wheel],assumptions=['d>0; distinguish yaw direction from an informal left/right path description while reversing.'])
add([263,265],'drive-sign-source-error','Opposite speeds and rotation direction','The table labels v_r=−v_l as clockwise; which qualification is necessary under the displayed equations?', ['It is clockwise only when v_r<0; opposite speeds alone specify in-place rotation, not its sign','It is always clockwise, even when v_r>0','It always produces straight backward motion','Its yaw rate is always zero because the average speed is zero'],0,'Opposite wheel speeds make v=0, but ω=v_r/d retains the sign of the right-wheel speed.', ['This states the missing sign condition.','Positive v_r gives positive counterclockwise yaw.','The average speed vanishes, so there is no center translation.','Zero average and nonzero difference can coexist.'],typ='derivation',steps=['Substitute v_l=−v_r into the average: v=0.','Substitute into the difference: ω=(2v_r)/(2d)=v_r/d.','Thus the sign depends on v_r; d is positive.'],formulas=[wheel],assumptions=['The source’s unconditional clockwise label is incomplete; counterclockwise yaw is positive.'],evidence={263:'Motion table: v_r=v_l straight; v_r>v_l left; v_r<v_l right; v_r=−v_l labeled clockwise. The last label omits the sign of v_r.',265:'Equations: v=(v_r+v_l)/2; ω=(v_r−v_l)/(2d), with heading rateφ_dot=ω.'})
add(264,'mobile-configuration','Planar mobile-robot configuration','Which variables describe the displayed planar robot pose?', ['x, y and headingφ','x, y, z and no orientation','Only the two wheel angular rates','Only the distance traveled by the right wheel'],0,'The configuration is position(x,y) and orientationφ; wheel rates are inputs to its motion model.', ['These are the displayed configuration variables.','The model is planar and explicitly includes orientation.','Inputs/rates are not the position-and-heading state.','One wheel travel does not determine the full planar pose.'],typ='definition',diff='easy')
