add(265,'differential-drive-equations','Mean and difference of wheel speeds','Which pair is correct for track width2d?', ['v=(v_r+v_l)/2;ω=(v_r−v_l)/(2d)','v=v_r+v_l;ω=(v_r−v_l)/d','v=(v_r−v_l)/2;ω=(v_r+v_l)/(2d)','v=(v_r+v_l)/(2d);ω=(v_r−v_l)/2'],0,'The center speed is the mean and yaw rate is the right-left difference divided by total track width.', ['Both the averaging factor and full track width are correct.','Both values are doubled.','This exchanges mean and difference.','This exchanges the units and geometric divisors.'],typ='match',formulas=[wheel])
add(265,'differential-drive-numerical','Computing forward and yaw speeds','Let r=0.10 m,d=0.25 m,u_l=2 rad/s,u_r=4 rad/s; what are v andω?', ['0.30 m/s and0.40 rad/s','0.60 m/s and0.80 rad/s','0.30 m/s and0.80 rad/s','0.10 m/s and1.20 rad/s'],0,'The wheel linear speeds are0.2 and0.4 m/s; their mean is0.3 and their difference divided by0.5 is0.4.', ['Both computations use the stated radius and total track width.','This omits both factors of2.','The forward speed is correct, but yaw incorrectly divides by half-track d.','This confuses sum and difference.'],typ='numerical',steps=['v_l=0.10×2=0.20 m/s;v_r=0.10×4=0.40 m/s.','v=(0.40+0.20)/2=0.30 m/s.','ω=(0.40−0.20)/(2×0.25)=0.40 rad/s.'],formulas=[wheel])
add(265,'mobile-pose-rate','Heading and world-frame velocity','For v=0.30 m/s,ω=0.40 rad/s andφ=90°, what is the ordered vector (x_dot,y_dot,φ_dot)?', ['(0,0.30,0.40)','(0.30,0,0.40)','(0,−0.30,0.40)','(0,0.30,0)'],0,'At90° the forward direction is world+y, while yaw rate remains0.40 rad/s.', ['This rotates the forward velocity into+y and retains yaw.','This uses a zero heading.','This uses a−90° heading.','Current heading does not force yaw rate to vanish.'],typ='numerical',steps=['cos90°=0;sin90°=1.','x_dot=0.30×0=0 m/s.','y_dot=0.30×1=0.30 m/s;φ_dot=0.40 rad/s.'],formulas=[pose],assumptions=['First two entries are m/s; the third is rad/s.'])
add(265,'drive-matrix-order','Reading the matrix row order','The displayed matrix multiplies (u_l,u_r); which order does it use for the resulting state-rate vector?', ['(φ_dot,x_dot,y_dot)','(x_dot,y_dot,φ_dot)','(y_dot,φ_dot,x_dot)','(v_l,v_r,φ)'],0,'Its first row is the opposite-sign yaw coefficients, followed by the cosine x row and sine y row.', ['This matches the matrix ordering.','This is a common pose ordering but not the displayed row order.','This permutes the rows incorrectly.','The output is a pose-rate vector, not wheel speeds and an angle.'],typ='table',formulas=[wheel,pose],evidence={265:'Displayed vector is [φ_dot,x_dot,y_dot]^T; matrix rows are [−r/(2d),r/(2d)],[(r/2)cosφ,(r/2)cosφ],[(r/2)sinφ,(r/2)sinφ]; input is[u_l,u_r]^T.'})
add(265,'drive-matrix-order','Signs in the wheel-rate matrix','Which yaw row is correct when the input order is (u_l,u_r)?', ['[−r/(2d), +r/(2d)]','[+r/(2d), −r/(2d)]','[+r/2,+r/2]','[−r/d,+r/d]'],0,'The yaw equation is proportional to u_r−u_l and divided by total wheel separation2d.', ['This preserves the input order, sign and denominator.','This reverses the yaw convention.','This computes forward speed rather than yaw.','This doubles yaw by using half-track instead of full track.'],typ='table',formulas=[wheel])
add(265,'drive-parameter-sensitivity','Wheel separation sensitivity','Keep the wheel linear speeds fixed and double the separation2d; what happens to v andω?', ['v is unchanged;ω is halved','Both v andω are halved','v is doubled;ω is unchanged','Both v andω are doubled'],0,'The speed average has no d term, while yaw is inversely proportional to total track width.', ['This follows the two equations.','Only yaw depends on separation.','The forward speed does not scale with separation.','Doubling the denominator reduces yaw rather than increasing it.'],typ='conceptual',formulas=[wheel])
add(265,'drive-parameter-sensitivity','Wheel radius sensitivity','Keep both angular wheel rates and separation fixed, then double the common wheel radius; what happens?', ['Both forward speed and yaw rate double','Only forward speed doubles; yaw is unchanged','Only yaw doubles; forward speed is unchanged','Both values are halved'],0,'With fixed angular rates, each equation has the common radius as a linear multiplier.', ['Both expressions are proportional to r.','Yaw also includes r when using angular wheel rates.','Forward speed also includes r.','The multiplier grows rather than shrinks.'],typ='conceptual',formulas=[wheel])
invwheel=F('u_l=(v−dω)/r;u_r=(v+dω)/r',{'u_l,u_r':'left and right wheel angular rates','v':'requested forward speed','ω':'requested counterclockwise yaw rate','d':'half-track width','r':'wheel radius'},{'u_l,u_r,ω':'rad/s','v':'m/s','d,r':'m'},['r>0; pure rolling and equal radii.'])
add(265,'inverse-wheel-map','Deriving wheel commands','Which wheel commands achieve the requested v andω in the stated model?', ['u_l=(v−dω)/r;u_r=(v+dω)/r','u_l=(v+dω)/r;u_r=(v−dω)/r','u_l=(v−2dω)/r;u_r=(v+2dω)/r','u_l=r(v−dω);u_r=r(v+dω)'],0,'Solve the sum and difference equations: r(u_r+u_l)=2v and r(u_r−u_l)=2dω.', ['This solves both equations.','This reverses the yaw sign.','This doubles the required wheel-speed difference.','Converting linear wheel speed to angular rate requires division by r.'],typ='derivation',steps=['Write u_r+u_l=2v/r.','Write u_r−u_l=2dω/r.','Add and divide by2 to obtain u_r.','Subtract and divide by2 to obtain u_l.'],formulas=[wheel,invwheel])
