add(265,'in-place-numerical','Signed in-place rotation','For r=0.10 m,d=0.25 m,u_l=−3 rad/s andu_r=3 rad/s, what motion follows?', ['v=0 andω=+1.2 rad/s, counterclockwise','v=0 andω=−1.2 rad/s, clockwise','v=0.3 m/s andω=0','v=0 andω=+0.6 rad/s'],0,'The equal/opposite wheel rates cancel in the mean and differ by6 rad/s.', ['The computed positive yaw is counterclockwise.','This reverses the stated sign convention.','This uses the magnitude rather than the signed sum.','This drops the factor2 in the wheel-rate difference.'],typ='numerical',steps=['v=0.10(3−3)/2=0.','ω=0.10(3−(−3))/(2×0.25)=1.2 rad/s.','Positive yaw is counterclockwise.'],formulas=[wheel])
add(265,'no-slip-lateral','Instantaneous lateral-velocity constraint','From x_dot=v cosφ andy_dot=v sinφ, which combination must vanish under the stated no-slip model?', ['−x_dot sinφ+y_dot cosφ','x_dot cosφ+y_dot sinφ','x_dot+y_dot for every heading','φ_dot for every unequal wheel-speed pair'],0,'The component perpendicular to the heading is−v cosφ sinφ+v sinφ cosφ=0.', ['This is the zero lateral component.','This is the forward component v, not generally zero.','The sum need not vanish.','Unequal wheel speeds generally produce nonzero yaw.'],typ='derivation',steps=['Substitute x_dot=v cosφ andy_dot=v sinφ.','The lateral component is−v cosφ sinφ+v sinφ cosφ.','The terms cancel.'],formulas=[pose],assumptions=['Pure rolling with no sideways slip; this is a consequence of the displayed model, not a claim about every real surface.'])
add([249,266],'six-joint-qualification','Six freedoms and a general spatial task','How should the summary’s six-joint statement be interpreted without overclaiming?', ['Six independent one-DOF joints can provide six local pose freedoms when the configuration is nonsingular; task and joint constraints still matter','Any six joints guarantee every pose is reachable with a unique solution','Any robot with fewer than six joints cannot perform any useful task','Counting six matrix entries proves the robot has six independent freedoms'],0,'A general spatial pose has six coordinates locally, but independence, singularities, workspace and the chosen task determine actual capability.', ['This retains the intended six-freedom motivation with necessary qualifications.','Joint count alone does not guarantee reachability or uniqueness.','Lower-dimensional tasks can use fewer freedoms.','Matrix entries are constrained and are not independent joint coordinates.'],typ='conceptual',assumptions=['The interpretation concerns general spatial pose control using one-DOF joints, not every possible task or multi-DOF joint design.'])
